import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)


def lcm(a, b):
    return a * b // gcd(a, b)


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        nums = [abs(int(x)) for x in line.split() if x.strip()]
        if not nums:
            continue
        g = nums[0]
        l = nums[0]
        for n in nums[1:]:
            g = math.gcd(g, n)
            l = lcm(l, n)
        print(g, l)


if __name__ == "__main__":
    main()
